mapper.update:
update track_info
set order_num = order_num - 1
where album_id = #{albumId}
  and order_num > #{orderNum}
  and is_deleted = 0

mapper.select:
select album.id as albumId, album.album_title, track.id as trackId, track.track_title, track.media_duration, if(track.cover_url is null or track.cover_url = '', album.cover_url, track.cover_url) as coverUrl, track.status, track.create_time as createTime, MAX(IF(stat.stat_type = '0701', stat.stat_num, 0)) as playStatNum, MAX(IF(stat.stat_type = '0702', stat.stat_num, 0)) as collectStatNum, MAX(IF(stat.stat_type = '0703', stat.stat_num, 0)) as praiseStatNum, MAX(IF(stat.stat_type = '0704', stat.stat_num, 0)) as commentStatNum from track_info track left join track_stat stat on stat.track_id = track.id left join album_info album on album.id = track.album_id
track.user_id=#{vo.userId}
and track.status = #{vo.status}
and track.track_title like concat('%',#{vo.trackTitle},'%')
and track.is_deleted = 0
group by track.id order by track.id desc

mapper.update:
update track_stat
set stat_num = stat_num + #{count}
where track_id = #{trackId}
  and stat_type = #{statType}
